<template><div class="login"><el-card style="width:380px"><h2>{{ t('管理后台登录') }}</h2><el-form @submit.prevent="submit"><el-form-item><el-input v-model="email" type="email" :placeholder="t('邮箱')" required/></el-form-item><el-form-item><el-input v-model="password" type="password" :placeholder="t('密码')" required show-password/></el-form-item><el-alert v-if="error" :title="error" type="error" show-icon style="margin-bottom:15px"/><el-button native-type="submit" type="primary" style="width:100%">{{ t('登录') }}</el-button></el-form></el-card></div></template>
<script setup>import { ref } from 'vue';import { useRouter } from 'vue-router';import { token, identity } from '../api';import { t } from '../i18n';const router=useRouter(),email=ref(''),password=ref(''),error=ref('');async function submit(){error.value='';try{const r=await fetch('/api/v1/auth/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email:email.value,password:password.value,device:'Web administration'})});const data=await r.json();if(!r.ok)throw Error(data.error);if(data.user.role!=='admin'){await fetch('/api/v1/auth/logout',{method:'POST',headers:{Authorization:'Bearer '+data.token}});throw Error(t('仅管理员可访问'))}token.value=data.token;identity.value=data.user;sessionStorage.setItem('axleo_admin',data.token);router.push('/dashboard')}catch(e){error.value=e.message}}</script><style scoped>.login{height:100vh;display:grid;place-items:center;background:#f5f3ee}</style>
